/**
 * @stars-w/dsh-group-chat — client 群聊面板 v2。
 *
 * 交互形态（基于会话的群聊，不隔离会话）：
 *  - 指令呼起：主会话输入 /group-chat <任务>（host 命令）→ 引擎建团并自动讨论，
 *    client 后台轮询感知活动后自动打开右侧竖长面板
 *  - 右侧竖长停靠面板（shell.overlay，无全屏遮罩）：紧凑头部 + 可折叠设置区 +
 *    消息流 + 底部参与输入框（用户可插话，角色会回应）
 *  - 会话头部「群聊」按钮保留（打开面板查看/管理）
 *
 * 与 host 通信：同源 fetch（webServer /dsh-group-chat 前缀路由）：
 *  - GET  /api/state —— 轮询快照（打开 500ms / 后台 2s，版本去重）
 *  - POST /api/<action> —— generate-roles/start/pause/resume/skip/stop/reroll/
 *    update-roles/sync-settings/chat/export-md
 */

import { createElement as h, useState, useEffect, useRef, useCallback } from 'react'

/* ───────────────────────── 共享 bus（入口 ↔ 面板 ↔ 自动探测） ───────────────────────── */

/** 收起哨兵：确保 dismissedTask 永远不等于任何任务文本（关闭后绝不自动弹出）。 */
const DISMISS_SENTINEL = '\u0000dismissed'

const bus = {
  open: false,
  sessionId: '',      // 群聊绑定的发起会话；面板仅在该会话活跃时显示
  dismissedTask: '',  // 用户点击 × 收起时的任务；新任务（不同文本）才允许自动弹出
  lastTask: '',       // 最近一次快照的任务文本（收起时取用）
  listeners: new Set(),
}

function subscribeBus(fn) {
  bus.listeners.add(fn)
  return () => bus.listeners.delete(fn)
}

function dispatchBus() {
  for (const fn of bus.listeners) { try { fn() } catch { /* ignore */ } }
}

function openPanel(sessionId) {
  if (sessionId) bus.sessionId = sessionId
  bus.dismissedTask = '' // 手动打开/探测打开均允许再次自动弹出
  bus.open = true
  dispatchBus()
}

function closePanel() {
  // 以最近一次快照的任务为"收起标记"；无快照用哨兵（绝不等于任何任务文本）
  bus.dismissedTask = bus.lastTask || DISMISS_SENTINEL
  bus.open = false
  dispatchBus()
}

/* ───────────────────────── Host API ───────────────────────── */

/**
 * 面板 API 基址：host 半注册在 connection 共享 `/api` 通道下的精确 Fetch 路由。
 * 与运行方式无关——web 版（webserver 把 `/api` 前缀交给同一个 handler）与
 * 桌面版（desktop-host 转发 `/api/*`）走同一条路径，因此这里不使用任何
 * 自建前缀路由。
 */
const API = '/api/group-chat'

async function fetchState() {
  const res = await fetch(API + '/state', { cache: 'no-store' })
  if (!res.ok) throw new Error('HTTP ' + res.status)
  return res.json()
}

async function postAction(action, extra = {}) {
  const res = await fetch(API + '/command', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ action, sessionId: bus.sessionId, ...extra }),
  })
  const data = await res.json().catch(() => ({ ok: false }))
  if (!res.ok || data.ok !== true) {
    throw new Error((data && data.error) || '请求失败（' + res.status + '）')
  }
  return data
}

