function adoptStyles() {
  if (typeof document === 'undefined') return
  if (document.getElementById(STYLE_ID) !== null) return
  const style = document.createElement('style')
  style.id = STYLE_ID
  style.dataset.plugin = '@stars-w/dsh-group-chat'
  style.textContent = CSS
  document.head.appendChild(style)
}

/* ───────────────────────── 小部件 ───────────────────────── */

/**
 * 安全 markdown 渲染（零依赖）：把 LLM 消息文本解析为 React 元素树；
 * 文本始终按字符串输出，任何 HTML 标记都不会被解释（无注入面）。
 * 支持：## 标题 / - 列表 / 1. 有序列表 / > 引用 / ``` 代码块 / --- 分隔 /
 *       **粗体** / *斜体* / `代码` / [链接](url) / ~~删除~~。
 * 字号遵循 .dshgc-msgText 的窄面板缩放宽限（显著小于标准 md）。
 */
function mdInline(text, keyPrefix) {
  const out = []
  const re = /(\*\*[^*]+\*\*|\*[^*]+\*|`[^`]+`|\[[^\]]+\]\([^)]+\)|~~[^~]+~~)/g
  let last = 0
  let m
  let i = 0
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) out.push(text.slice(last, m.index))
    const tok = m[0]
    const key = keyPrefix + (i++)
    if (tok.startsWith('**')) out.push(h('strong', { key }, tok.slice(2, -2)))
    else if (tok.startsWith('`')) out.push(h('code', { key }, tok.slice(1, -1)))
    else if (tok.startsWith('[')) {
      const mm = /^\[([^\]]+)\]\(([^)]+)\)$/.exec(tok)
      if (mm) {
        // 协议白名单：仅 http/https/mailto（LLM 文本视为不可信数据，防 javascript: 等）
        const href = mm[2].trim()
        const safe = /^(https?:|mailto:)/i.test(href)
        out.push(safe
          ? h('a', { key, href, target: '_blank', rel: 'noreferrer' }, mm[1])
          : mm[1])
      } else out.push(tok)
    } else if (tok.startsWith('*')) out.push(h('em', { key }, tok.slice(1, -1)))
    else if (tok.startsWith('~~')) out.push(h('del', { key }, tok.slice(2, -2)))
    last = m.index + tok.length
  }
  if (last < text.length) out.push(text.slice(last))
  return out
}

function mdToReact(markdown) {
  const lines = String(markdown || '').split('\n')
  const nodes = []
  let i = 0
  let k = 0
  const key = () => 'md' + (k++)
  while (i < lines.length) {
    const t = lines[i].trim()
    if (t === '') { i += 1; continue }
    if (t.startsWith('```')) { // 代码块
      const buf = []
      i += 1
      while (i < lines.length && !lines[i].trim().startsWith('```')) { buf.push(lines[i]); i += 1 }
      i += 1
      nodes.push(h('pre', { key: key() }, h('code', null, buf.join('\n'))))
      continue
    }
    const heading = /^(#{1,4})\s+(.+)$/.exec(t)
    if (heading) {
      const level = heading[1].length
      nodes.push(h('h' + level, { key: key() }, ...mdInline(heading[2], 'h' + k)))
      i += 1
      continue
    }
    if (/^---+$/.test(t)) { nodes.push(h('hr', { key: key() })); i += 1; continue }
    if (t.startsWith('>')) { // 引用
      const buf = []
      while (i < lines.length && lines[i].trim().startsWith('>')) { buf.push(lines[i].trim().replace(/^>\s?/, '')); i += 1 }
      nodes.push(h('blockquote', { key: key() }, ...mdInline(buf.join(' '), 'q' + k)))
      continue
    }
    if (/^[-*•]\s+/.test(t) || /^\d+[.)]\s+/.test(t)) { // 列表
      const ordered = /^\d+[.)]\s+/.test(t)
      const items = []
      while (i < lines.length) {
        const line = lines[i].trim()
        const um = /^[-*•]\s+/.exec(line)
        const om = /^\d+[.)]\s+/.exec(line)
        if (ordered ? om : um) {
          items.push(h('li', { key: items.length }, ...mdInline(line.replace(ordered ? om[0] : um[0], ''), 'li' + k + items.length)))
          i += 1
        } else break
      }
      nodes.push(h(ordered ? 'ol' : 'ul', { key: key() }, items))
      continue
    }
    // 普通段落（连续行合并，行间 <br/>）
    const para = []
    while (i < lines.length) {
      const line = lines[i]
      const lt = line.trim()
      if (lt === '' || /^(#{1,4}\s|```|---$|>\s|[-*•]\s|\d+[.)]\s)/.test(lt)) break
      para.push(line)
      i += 1
    }
    nodes.push(h('p', { key: key() }, para.map((line, idx) => {
      const children = []
      if (idx > 0) children.push(h('br', { key: 'br' + idx }))
      children.push(...mdInline(line, 'p' + k + idx))
      return children
    })))
  }
  return nodes
}

const AVATAR_COLORS = ['#5ad1a6', '#6ab0f3', '#f3b562', '#e88a8a', '#b48cf2', '#7dd3a8', '#f2a06b', '#89c2f0']

function avatarColor(roleId) {
  if (!roleId) return '#999'
  const m = /(\d+)/.exec(roleId)
  const index = m ? Number(m[1]) : 0
  return AVATAR_COLORS[index % AVATAR_COLORS.length]
}

function roleInitial(name) {
  return String(name || '?').slice(0, 1).toUpperCase()
}

const PHASE_LABEL = {
  idle: '待命',
  'generating-roles': '拉群中',
  discussing: '讨论中',
  summarizing: '总结中',
  done: '已完成',
  error: '出错',
}

/* ───────────────────────── 入口按钮 ───────────────────────── */

function HeaderAction({ sessionId }) {
  return h('button', {
    className: 'dshgc-trigger',
    title: '多角色群聊：基于会话发起群聊（也可用 /group-chat <任务> 指令呼起）',
    onClick: () => openPanel(sessionId),
  }, '💬', h('span', null, '群聊'))
}

/* ───────────────────────── 面板位置（拖动 + 持久化） ───────────────────────── */

const PANEL_POS_KEY = 'dsh-group-chat-panel-pos'

function loadPanelPos() {
  try {
    const raw = localStorage.getItem(PANEL_POS_KEY)
    if (!raw) return null
    const p = JSON.parse(raw)
    if (typeof p.x === 'number' && typeof p.y === 'number') {
      return { x: Math.max(4, Math.min(p.x, window.innerWidth - 396)), y: Math.max(4, Math.min(p.y, window.innerHeight - 120)) }
    }
  } catch { /* 忽略损坏数据 */ }
  return null
}

function savePanelPos(pos) {
  try {
    if (pos) localStorage.setItem(PANEL_POS_KEY, JSON.stringify(pos))
    else localStorage.removeItem(PANEL_POS_KEY)
  } catch { /* 存储不可用：静默 */ }
}

/* ───────────────────────── 悬浮按钮位置（拖动 + 持久化） ───────────────────────── */

const FLOAT_POS_KEY = 'dsh-group-chat-float-pos'
/** 悬浮按钮边长（与 .dshgc-float 的 width/height 一致）。 */
const FLOAT_SIZE = 46

/**
 * 把悬浮按钮位置限制在视口内（四周留 8px）。
 * @param {number} x 期望的 left
 * @param {number} y 期望的 top
 * @returns {{x: number, y: number}} 视口内的位置
 */
function clampFloatPos(x, y) {
  const vw = window.innerWidth
  const vh = window.innerHeight
  return {
    x: Math.max(8, Math.min(Math.round(x), vw - FLOAT_SIZE - 8)),
    y: Math.max(8, Math.min(Math.round(y), vh - FLOAT_SIZE - 8)),
  }
}

/** 读取用户拖动的悬浮按钮位置；未拖动过返回 null（走默认自适应位置）。 */
function loadFloatPos() {
  try {
    const raw = localStorage.getItem(FLOAT_POS_KEY)
    if (!raw) return null
    const p = JSON.parse(raw)
    if (typeof p.x === 'number' && typeof p.y === 'number') return clampFloatPos(p.x, p.y)
  } catch { /* 忽略损坏数据 */ }
  return null
}

function saveFloatPos(pos) {
  try {
    if (pos) localStorage.setItem(FLOAT_POS_KEY, JSON.stringify(pos))
    else localStorage.removeItem(FLOAT_POS_KEY)
  } catch { /* 存储不可用：静默 */ }
}

/* ───────────────────────── 面板 ───────────────────────── */

function Panel() {
  const [, setOpenTick] = useState(0)
  const [snap, setSnap] = useState(null)
  const [offline, setOffline] = useState(false)
  const [draft, setDraft] = useState('')
  const [compose, setCompose] = useState('')
  const [notice, setNotice] = useState('')
  const [generating, setGenerating] = useState(false)
  const [showSettings, setShowSettings] = useState(false)
  const [showRoleForm, setShowRoleForm] = useState(false)
  const [roleDraft, setRoleDraft] = useState({ name: '', persona: '', duty: '' })
  const msgsRef = useRef(null)
  const overlayRef = useRef(null)
  // 拖动（仅头部空白区；拖动后进入浮动模式，位置持久化）
  const [pos, setPos] = useState(() => loadPanelPos())
  const posRef = useRef(pos)
  posRef.current = pos
  const dragRef = useRef(null)
  const dragHandlersRef = useRef(null) // 始终指向最近一次渲染的 move/end（供卸载清理）
  const clampViewport = (x, y) => {
    const vw = window.innerWidth
    const vh = window.innerHeight
    return {
      x: Math.max(4, Math.min(Math.round(x), vw - 396)),
      // 底部留出面板最小高度空间（面板高度 = min(640, vh - y - 16)，最小 200）
      y: Math.max(4, Math.min(Math.round(y), vh - 220)),
    }
  }
  const onDragMove = (e) => {
    const d = dragRef.current
    if (!d) return
    setPos(clampViewport(e.clientX - d.dx, e.clientY - d.dy))
  }
  const onDragEnd = () => {
    if (!dragRef.current) return
    dragRef.current = null
    const h = dragHandlersRef.current
    if (h) {
      window.removeEventListener('pointermove', h.move)
      window.removeEventListener('pointerup', h.end)
      window.removeEventListener('blur', h.end)
    }
    savePanelPos(posRef.current)
  }
  dragHandlersRef.current = { move: onDragMove, end: onDragEnd }
  useEffect(() => () => {
    const h = dragHandlersRef.current
    if (h) {
      window.removeEventListener('pointermove', h.move)
      window.removeEventListener('pointerup', h.end)
      window.removeEventListener('blur', h.end)
    }
    dragRef.current = null
  }, [])
  const onDragStart = (e) => {
    if (e.button !== 0 || !overlayRef.current) return
    if (e.target && e.target.closest && e.target.closest('button')) return // 按钮区不拖动
    e.preventDefault()
    const rect = overlayRef.current.getBoundingClientRect()
    dragRef.current = { dx: e.clientX - rect.left, dy: e.clientY - rect.top }
    const h = dragHandlersRef.current
    if (h) {
      window.addEventListener('pointermove', h.move)
      window.addEventListener('pointerup', h.end)
      window.addEventListener('blur', h.end)
    }
  }

  useEffect(() => subscribeBus(() => setOpenTick((n) => n + 1)), [])
  useEffect(() => { adoptStyles() }, [])

  // 打开时 500ms 轮询快照（版本去重）
  useEffect(() => {
    if (!bus.open) return
    let alive = true
    let last = 0
    const tick = async () => {
      try {
        const snapNow = await fetchState()
        if (!alive) return
        setOffline(false)
        setGenerating(snapNow.phase === 'generating-roles')
        if (snapNow.version !== last) {
          last = snapNow.version
          setSnap(snapNow)
          if (typeof snapNow.task === 'string') bus.lastTask = snapNow.task
        }
      } catch {
        if (alive) setOffline(true)
      }
    }
    tick()
    const timer = setInterval(tick, 500)
    return () => { alive = false; clearInterval(timer) }
  }, [bus.open])

  // 新消息自动滚动到底
  useEffect(() => {
    const el = msgsRef.current
    if (el) el.scrollTop = el.scrollHeight
  }, [snap && snap.version])

  useEffect(() => {
    if (snap && snap.task && draft === '') setDraft(snap.task)
  }, [snap, draft])

  const phase = snap ? snap.phase : 'idle'
  const roles = snap ? snap.roles : []
  const messages = snap ? snap.messages : []

  const run = useCallback(async (fn, okText) => {
    setNotice('')
    try {
      await fn()
      if (okText) setNotice(okText)
    } catch (err) {
      setNotice('操作失败：' + String(err && err.message ? err.message : err).slice(0, 160))
    }
  }, [])

  const send = useCallback(() => {
    const text = compose.trim()
    if (text === '') return
    setCompose('')
    void run(() => postAction('chat', { text }), '')
  }, [compose, run])

  // md 渲染缓存：流式期间仅重解析变化的文本（消息 id 稳定），避免每 chunk 全量重渲染
  const mdCacheRef = useRef(new Map())
  const renderMsg = (m) => {
    let cached = mdCacheRef.current.get(m.id)
    if (!cached || cached.text !== m.text) {
      cached = { text: m.text, node: m.failed === true ? [m.text] : mdToReact(m.text) }
      mdCacheRef.current.set(m.id, cached)
    }
    return cached.node
  }

  const canGenerate = phase !== 'discussing' && phase !== 'generating-roles' && phase !== 'summarizing'
  const inDiscuss = phase === 'discussing'
  const paused = inDiscuss && snap && snap.paused === true

  const controls = h('div', { className: 'dshgc-row' },
    (phase === 'idle' || phase === 'done' || phase === 'error') && roles.length > 0
      ? h('button', {
          className: 'dshgc-btn dshgc-btn-primary',
          disabled: offline,
          onClick: () => run(async () => {
            await postAction('start')
          }),
        }, '▶ 开始讨论')
      : null,
    inDiscuss && !paused
      ? h('button', { className: 'dshgc-btn', onClick: () => run(() => postAction('pause')) }, '⏸ 暂停')
      : null,
    inDiscuss && paused
      ? h('button', { className: 'dshgc-btn dshgc-btn-primary', onClick: () => run(() => postAction('resume')) }, '▶ 继续')
      : null,
    inDiscuss
      ? h('button', { className: 'dshgc-btn', onClick: () => run(() => postAction('skip')) }, '⏭ 跳过')
      : null,
    inDiscuss
      ? h('button', { className: 'dshgc-btn dshgc-btn-danger', onClick: () => run(() => postAction('stop')) }, '■ 停止')
      : null,
    messages.length > 0
      ? h('button', { className: 'dshgc-btn', onClick: () => run(() => postAction('export-md')) }, '📄 导出 MD')
      : null,
  )

  const overlayStyle = pos
    ? {
        left: pos.x,
        top: pos.y,
        right: 'auto',
        bottom: 'auto',
        height: Math.max(200, Math.min(640, window.innerHeight - pos.y - 16)),
      }
    : undefined

  return h('div', { className: 'dshgc-overlay', ref: overlayRef, 'data-float': pos ? '1' : undefined, style: overlayStyle },
    h('div', { className: 'dshgc-panel' },
      h('div', { className: 'dshgc-head', onPointerDown: onDragStart, title: '按住空白处可拖动面板' },
        h('span', { className: 'dshgc-avatar', style: { background: '#6ab0f3' } }, '💬'),
        h('div', { className: 'dshgc-title' },
          '群聊讨论',
          h('span', { className: 'dshgc-taskMini' }, (snap && snap.task) ? '· ' + snap.task.slice(0, 26) : ''),
        ),
        h('span', { className: 'dshgc-badge' }, PHASE_LABEL[phase] || phase),
        h('button', {
          className: 'dshgc-iconbtn',
          title: showSettings ? '收起设置' : '任务与角色设置',
          onClick: () => setShowSettings((v) => !v),
        }, showSettings ? '▾' : '⚙'),
        h('button', {
          className: 'dshgc-iconbtn dshgc-close',
          onClick: () => closePanel(),
          title: '收起面板（群聊在后台继续，完成后结论仍会回到会话）',
        }, '×'),
      ),

      showSettings
        ? h('div', { className: 'dshgc-settings' },
            offline
              ? h('div', { className: 'dshgc-offline' }, '⚠ 与群聊服务断开（插件可能已卸载/重载）')
              : null,
            notice
              ? h('div', { className: 'dshgc-notice' }, notice)
              : null,
            h('div', { className: 'dshgc-label' }, '任务 / 设计需求'),
            h('textarea', {
              className: 'dshgc-textarea',
              placeholder: '输入任务或设计方案…',
              value: draft,
              disabled: inDiscuss || generating,
              onChange: (e) => setDraft(e.target.value),
            }),
            h('div', { className: 'dshgc-row' },
              h('label', { className: 'dshgc-toggle', title: '成员被点名后可自主调用 subagent 深度推理；随时切换，当前发言/推理中的成员不受影响，下次发言时生效' },
                h('input', {
                  type: 'checkbox',
                  checked: snap ? snap.allowDeepReasoning === true : true,
                  onChange: (e) => run(async () => {
                    await postAction('sync-settings', { allowDeepReasoning: e.target.checked })
                  }),
                }),
                ' 允许成员深度推理',
              ),
            ),
            h('div', { className: 'dshgc-row' },
              h('button', {
                className: 'dshgc-btn dshgc-btn-primary',
                disabled: !canGenerate || offline || (draft.trim() === ''),
                onClick: () => run(async () => {
                  setNotice('正在生成角色团队…')
                  await postAction('generate-roles', { task: draft })
                  setNotice('')
                }),
              }, generating ? '⏳ 生成中…' : '✨ 生成角色团队'),
            ),
            (roles.length > 0 || (snap && snap.host))
              ? h('div', {},
                  h('div', { className: 'dshgc-label' }, '角色团队' + (snap && snap.host ? '（主持人 + ' + roles.length + ' 专家）' : `（${roles.length}）`)),
                  h('div', { className: 'dshgc-roles' },
                    snap && snap.host
                      ? h('span', {
                          className: 'dshgc-roleChip dshgc-hostChip', key: 'host',
                          title: '主持人：' + ((snap.host.duty ? '【' + snap.host.duty + '】' : '') + snap.host.persona) + '（主持人不参与增删改，更换请重新生成角色团队）',
                        },
                          h('span', { className: 'dshgc-avatar', style: { background: '#f3b562' } }, '主'),
                          snap.host.name,
                          h('span', { className: 'dshgc-hostTag' }, '主持'),
                        )
                      : null,
                    roles.map((r) => h('span', { className: 'dshgc-roleChip', key: r.id, title: (r.duty ? '【' + r.duty + '】' : '') + r.persona },
                      h('span', { className: 'dshgc-avatar', style: { background: avatarColor(r.id) } }, roleInitial(r.name)),
                      r.name,
                      h('button', {
                        className: 'dshgc-rm', title: '让 TA 重新发言',
                        onClick: (e) => { e.stopPropagation(); void run(() => postAction('reroll', { roleId: r.id })) },
                      }, '↻'),
                      h('button', {
                        className: 'dshgc-rm', title: '删除该角色',
                        disabled: inDiscuss,
                        onClick: (e) => { e.stopPropagation(); void run(() => postAction('update-roles', { roles: roles.filter((x) => x.id !== r.id) })) },
                      }, '✕'),
                    )),
                    showRoleForm
                      ? h('span', { className: 'dshgc-roleForm' },
                          h('input', { className: 'dshgc-input', placeholder: '角色名', value: roleDraft.name, onChange: (e) => setRoleDraft({ ...roleDraft, name: e.target.value }) }),
                          h('input', { className: 'dshgc-input', placeholder: 'persona 定位…', value: roleDraft.persona, onChange: (e) => setRoleDraft({ ...roleDraft, persona: e.target.value }) }),
                          h('input', { className: 'dshgc-input', placeholder: '职责（可选）', value: roleDraft.duty, onChange: (e) => setRoleDraft({ ...roleDraft, duty: e.target.value }) }),
                          h('div', { className: 'dshgc-row' },
                            h('button', { className: 'dshgc-btn dshgc-btn-primary', disabled: roleDraft.name.trim() === '' || roleDraft.persona.trim() === '', onClick: () => run(async () => {
                              await postAction('update-roles', { roles: [...roles, { id: 'r' + (roles.length + 1), name: roleDraft.name.trim(), persona: roleDraft.persona.trim(), duty: roleDraft.duty.trim() }] })
                              setRoleDraft({ name: '', persona: '', duty: '' })
                              setShowRoleForm(false)
                            }) }, '添加'),
                            h('button', { className: 'dshgc-btn', onClick: () => { setShowRoleForm(false); setRoleDraft({ name: '', persona: '', duty: '' }) } }, '取消'),
                          ),
                        )
                      : h('button', { className: 'dshgc-btn', disabled: inDiscuss, onClick: () => setShowRoleForm(true) }, '+ 加角色'),
                  ),
                )
              : null,
            h('div', { className: 'dshgc-row' },
              h('button', {
                className: 'dshgc-btn',
                disabled: !canGenerate || offline,
                onClick: () => run(() => postAction('generate-roles', { task: snap ? snap.task : draft })),
              }, '🔄 重新生成'),
            ),
          )
        : null,

      h('div', { className: 'dshgc-msgs', ref: msgsRef },
        messages.length === 0
          ? h('div', { className: 'dshgc-empty' },
              inDiscuss ? '讨论准备中…'
                : (generating ? '正在生成角色团队…' : '暂无发言。\n主会话输入 /group-chat <任务>，或点 ⚙ 配置任务后开始。'))
          : null,
        messages.map((m) => h('div', { className: 'dshgc-msg', key: m.id },
          h('span', {
            className: 'dshgc-avatar',
            style: { background: m.roleId === 'user' ? '#e88a8a' : (m.roleId === 'host' ? '#f3b562' : avatarColor(m.roleId)) },
          }, m.roleId === 'host' ? '主' : roleInitial(m.name)),
          h('div', { className: 'dshgc-msgBody' },
            h('div', { className: 'dshgc-msgName' }, m.name + (m.roleId === 'host' ? ' · 主持' : '')),
            h('div', { className: 'dshgc-msgText', 'data-failed': String(m.failed === true) },
              renderMsg(m)),
          ),
        )),
        inDiscuss && snap && snap.deepThinkingRoleId
          ? h('div', { className: 'dshgc-typing' }, '◌ ' + roleName(snap, snap.deepThinkingRoleId) + ' 正在调用 subagent 深度推理…')
          : null,
        inDiscuss && snap && snap.moderatorBusy === true
          ? h('div', { className: 'dshgc-typing' }, '● 主持人正在调度…')
          : null,
        inDiscuss && snap && snap.streamingRoleId
          ? h('div', { className: 'dshgc-typing' }, '● ' + roleName(snap, snap.streamingRoleId) + ' 正在输入…')
          : null,
      ),

      snap && snap.error
        ? h('div', { className: 'dshgc-error' }, '⚠ ' + snap.error)
        : null,
      offline
        ? h('div', { className: 'dshgc-offline' }, '⚠ 已与群聊服务断开')
        : null,

      (roles.length > 0 || messages.length > 0 || inDiscuss)
        ? h('div', { className: 'dshgc-section' }, controls)
        : null,

      h('div', { className: 'dshgc-compose' },
        h('textarea', {
          className: 'dshgc-compose-input',
          placeholder: '以主持人身份参与讨论：输入你的意见，点发送，角色会回应你…',
          value: compose,
          onChange: (e) => setCompose(e.target.value),
          onKeyDown: (e) => {
            if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() }
          },
        }),
        h('div', { className: 'dshgc-compose-row' },
          h('span', { className: 'dshgc-compose-hint' }, 'Enter 发送 · Shift+Enter 换行'),
          h('button', {
            className: 'dshgc-btn dshgc-btn-primary',
            disabled: offline || compose.trim() === '',
            onClick: send,
          }, '发送'),
        ),
      ),

      snap && snap.summary
        ? h('div', { className: 'dshgc-section' },
            h('div', { className: 'dshgc-label' }, '结论'),
            h('div', { className: 'dshgc-summary' }, ...mdToReact(snap.summary)),
            snap.mdPath
              ? h('div', { className: 'dshgc-path' }, '已保存：' + snap.mdPath)
              : null,
          )
        : null,
    ),
  )
}

function roleName(snap, roleId) {
  if (roleId === 'host') return (snap && snap.host && snap.host.name) || '主持人'
  const r = snap.roles.find((x) => x.id === roleId)
  return r ? r.name : '?'
}

/* ───────────────────────── 收起态悬浮按钮 ───────────────────────── */

/**
 * 面板收起时的悬浮入口：按讨论状态切换样式（待命/讨论中动画/出错）。
 * 可拖动调整位置（拖动后位置持久化；未拖动时贴会话内容区左上角），点击展开面板。
 * snap 由 OverlayHost 的低频轮询提供（面板关闭时 2s 一次）。
 */
function FloatingButton({ currentSession, snap }) {
  const phase = snap ? snap.phase : 'idle'
  const active = phase === 'discussing' || phase === 'generating-roles' || phase === 'summarizing'
  const cls = 'dshgc-float' + (active ? ' dshgc-float-active' : '') + (phase === 'error' ? ' dshgc-float-error' : '')
  const label = (snap && snap.task ? snap.task.slice(0, 18) + ' · ' : '') + (PHASE_LABEL[phase] || phase) + ' — 点击展开群聊面板（可拖动移动位置）'
  // 未拖动时的默认位置：主会话内容区左上角（会话侧栏右侧）；实测侧栏宽，CSS 292px 兜底
  const [sideW, setSideW] = useState(280)
  useEffect(() => {
    const el = document.querySelector('[class*="sidebarCol"]') || document.querySelector('aside')
    if (el) {
      const r = el.getBoundingClientRect()
      if (r.width > 100) setSideW(Math.round(r.width))
    }
  }, [])
  const [pos, setPos] = useState(() => loadFloatPos())
  const [dragging, setDragging] = useState(false)
  const movedRef = useRef(false)
  const cleanupRef = useRef(null)
  // 窗口尺寸变化：已拖动过的位置重新夹到视口内，避免按钮跑到屏幕外
  useEffect(() => {
    if (!pos) return
    const onResize = () => setPos((p) => (p ? clampFloatPos(p.x, p.y) : p))
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [pos])
  // 卸载时移除可能残留的拖动监听
  useEffect(() => () => { cleanupRef.current?.() }, [])

  const onPointerDown = (e) => {
    if (e.button !== undefined && e.button !== 0) return
    const rect = e.currentTarget.getBoundingClientRect()
    const start = { x: e.clientX, y: e.clientY, left: rect.left, top: rect.top }
    let latest = null
    movedRef.current = false
    setDragging(true)
    const onMove = (ev) => {
      const dx = ev.clientX - start.x
      const dy = ev.clientY - start.y
      if (!movedRef.current && Math.hypot(dx, dy) < 4) return
      movedRef.current = true
      latest = clampFloatPos(start.left + dx, start.top + dy)
      setPos(latest)
    }
    const finish = () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', finish)
      window.removeEventListener('pointercancel', finish)
      cleanupRef.current = null
      setDragging(false)
      if (latest) saveFloatPos(latest)
      // click 紧跟在 pointerup 之后派发：先让 click 消费 movedRef，再复位
      setTimeout(() => { movedRef.current = false }, 0)
    }
    cleanupRef.current = finish
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', finish)
    window.addEventListener('pointercancel', finish)
  }

  const onClick = () => {
    if (movedRef.current) return // 拖动结束的那次 click 不展开面板
    openPanel(currentSession)
  }

  return h('button', {
    className: cls + (dragging ? ' dshgc-float-dragging' : ''),
    title: label,
    'aria-label': label,
    style: pos ? { left: pos.x, top: pos.y } : { left: sideW + 12 },
    onPointerDown,
    onClick,
  }, '💬', active ? h('span', { className: 'dshgc-float-dots' }, h('i'), h('i'), h('i')) : null)
}

/* ───────────────────────── 注册与自动探测 ───────────────────────── */

function OverlayHost({ useSessions }) {
  const [tick, setTick] = useState(0)
  useEffect(() => subscribeBus(() => setTick((n) => n + 1)), [])

  // 当前活跃会话 id。DSH 0.1.x 的 SessionListState 带 `current` 字段；0.2.x 改成
  // { ids, byId, phase, projectionsBySession }，这里只能读到 undefined——归属判断
  // 必须允许"读不到当前会话"，否则面板会被整体藏掉。
  const currentSession = typeof useSessions === 'function'
    ? useSessions((s) => (s ? s.current : undefined))
    : undefined

  // 面板关闭时的低频轮询（2s）：
  //  1) 浮钮展示 phase 状态（讨论中动画/出错色/待命）
  //  2) 检测到新群聊活动（未收起的新任务）→ 自动打开面板
  // 归属优先用 bus.sessionId（点击/自动打开时记录），其次用快照里的发起会话；
  // 读不到当前会话（0.2.x）时不因此跳过探测，否则面板永远不自动打开。
  const [closedSnap, setClosedSnap] = useState(null)
  useEffect(() => {
    if (bus.open) return
    let alive = true
    const probe = async () => {
      try {
        const s = await fetchState()
        if (!alive || bus.open) return
        setClosedSnap(s)
        const active = s.phase === 'discussing' || s.phase === 'generating-roles' || s.phase === 'summarizing'
        if (!active) return
        if (s.task === bus.dismissedTask) return // 用户已收起同一任务：静默后台跑
        const owner = bus.sessionId !== '' ? bus.sessionId : s.sessionId
        if (owner && currentSession !== undefined && owner !== currentSession) return // 群聊属于其它会话
        openPanel(owner)
      } catch { /* host 不可达：静默 */ }
    }
    probe()
    const timer = setInterval(probe, 2000)
    return () => { alive = false; clearInterval(timer) }
  }, [currentSession, bus.open])

  void tick
  // 收起态：仅当群聊上下文存在且属于当前会话时显示左上方悬浮按钮
  if (!bus.open) {
    if (bus.sessionId !== '') {
      // 已绑定过群聊会话：只在那个会话显示；读不到当前会话（0.2.x）时不隐藏
      if (currentSession !== undefined && currentSession !== bus.sessionId) return null
    } else {
      // 未绑定：仅当引擎有群聊上下文（活动/任务），且任务归属于当前会话
      const s = closedSnap
      const hasContext = Boolean(s && (s.phase !== 'idle' || (s.task && s.task !== '')))
      if (!hasContext) return null // 新会话/空闲：不显示悬浮按钮
      if (s && s.sessionId !== '' && currentSession !== undefined && s.sessionId !== currentSession) return null // 任务属于其它会话
    }
    return h(FloatingButton, { currentSession, snap: closedSnap })
  }
  // 会话绑定：面板只属于发起会话（bus.sessionId）；切走即不显示，切回恢复。
  // 读不到当前会话（0.2.x）时以 bus.sessionId 为准，不做隐藏。
  if (bus.sessionId !== '' && currentSession !== undefined && currentSession !== bus.sessionId) return null
  return h(Panel, null)
}

export const inject = ['slots']

export function apply(ctx) {
  adoptStyles()
  ctx.effect(() => ctx.slots.inject('conversation.session.header.actions', () =>
    ctx.slots.register({
      name: 'conversation.session.header.actions',
      id: 'dsh-group-chat-open',
      order: 30,
    }, HeaderAction),
  ), '@stars-w/dsh-group-chat: header action')
  ctx.effect(() => ctx.slots.inject('shell.overlay', () =>
    ctx.slots.register({
      name: 'shell.overlay',
      id: 'dsh-group-chat-panel',
      order: 90,
    }, OverlayHost),
  ), '@stars-w/dsh-group-chat: overlay panel')
}
